 "John Calvin":{"life": "1509–1564 (Noyon, France; Geneva)", "era": "16th c.", "known": "French reformer and pastor in Geneva; the Institutes of the Christian Religion (1536, final form 1559) and commentaries on most books of the Bible. The Reformed tradition ('Calvinism') is named after him.", "spec": "God's sovereignty in salvation, Scripture, the church and the sacraments.", "contro": [["His part in the execution of Michael Servetus for heresy in Geneva (1553)", "https://en.wikipedia.org/wiki/Michael_Servetus"]]},
 "Irenaeus of Lyon":{"life": "b. before c. 155 (Smyrna); d. c. 200 (Lyon)", "era": "2nd c.", "known": "Bishop of Lyon in Gaul; Against Heresies (c. 180), the main early answer to Gnosticism; the Demonstration of the Apostolic Preaching.", "spec": "Recapitulation (Christ the new Adam), the goodness of creation, apostolic tradition and succession. Final judgment left unplaced: conditionalists cite him because life and immortality are God's gift, while he also speaks of eternal fire.", "contro": []},
 "Origen":{"life": "c. 185–c. 253 (Alexandria; Caesarea)", "era": "3rd c.", "known": "Alexandrian teacher and scholar; head of the Catechetical School; On First Principles, Contra Celsum and the Hexapla (six-column Old Testament). Tortured in the Decian persecution (250).", "spec": "Textual scholarship and allegorical reading of Scripture; free will; the hope of final restoration.", "contro": [["Condemned as a heretic by Emperor Justinian (543); the Second Council of Constantinople (553) may have anathematised him, or only teachings using his name. The church rejected his idea that souls existed before birth.", "https://en.wikipedia.org/wiki/Origen"]]},
 "George MacDonald":{"life": "1824–1905 (Huntly, Scotland)", "era": "19th c.", "known": "Scottish author, poet and Congregational minister; pioneer of fantasy fiction (Phantastes, The Princess and the Goblin). C.S. Lewis said he was 'closer... to the Spirit of Christ Himself' than any other writer.", "spec": "God as Father whose love will not give up on anyone; uneasy with Calvinist election (rejected limited election).", "contro": [["His preaching of God's universal love was poorly received at Arundel; his pay was halved and he resigned (1853).", "https://en.wikipedia.org/wiki/George_MacDonald"]]},
